import React from "react";
import { BrowserRouter, Route, Routes } from "react-router-dom";
import { KindeProvider } from "@kinde-oss/kinde-auth-react";
import Add from "./pages/Add";
import Home from "./pages/Home";
import MemberInfo from "./pages/MemberInfo";
import Attendees from "./pages/Attendees";
import Settings from "./pages/Settings";
import "./App.scss";
import "./components/SearchBar.scss";
import Header from "./components/Header"
import SideNav from "./components/SideNav"

const clientId = process.env.REACT_APP_CLIENT_ID
const domain = process.env.REACT_APP_DOMAIN
const redirectUri = process.env.REACT_APP_REDIRECT_URI
const logoutUri = process.env.REACT_APP_LOGOUT_URI

export default function App() {
  return (
    <main className="App">
      <KindeProvider
        clientId={import.meta.env.REACT_APP_CLIENT_ID}
        domain={import.meta.env.REACT_APP_DOMAIN}
        logoutUri={import.meta.env.REACT_APP_LOGOUT_URL}
        redirectUri={import.meta.env.REACT_APP_REDIRECT_URL}
      >
        <BrowserRouter>
        <Header />
        <SideNav />
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/add" element={<Add />} />
            <Route path="/memberInfo/:id" element={<MemberInfo />} />
            <Route path="/attendees" element={<Attendees />} />
            <Route path="/settings" element={<Settings />} />
          </Routes>

        </BrowserRouter>
      </KindeProvider>
    </main>
  );
}
